SELECT COUNT(*) FROM disasterevents d
JOIN coordinationandevaluation ce ON d.distregistry = ce.coord_dist_ref
WHERE (d.haz_level IN ('Severity-4', 'Severity-5') OR ce.safety_ranking = 'High Risk' OR ce.secincidentcount > 5);

SELECT COUNT(*) FROM operations o
JOIN coordinationandevaluation ce ON o.opsregistry = ce.coordopsref
WHERE o.emerglevel IN ('Black', 'Red') OR ce.safety_ranking = 'High Risk' OR ce.secincidentcount > 5;

SELECT COUNT(*) FROM disasterevents d
JOIN beneficiariesandassessments b ON d.distregistry = b.bene_dist_ref
WHERE d.haz_level IN ('Severity-4', 'Severity-5');

SELECT COUNT(*) FROM disasterevents d
JOIN beneficiariesandassessments b ON d.distregistry = b.bene_dist_ref
WHERE d.haz_level IN ('Severity-4', 'Severity-5') AND b.needs_assess_status = 'Critical';

SELECT DISTINCT b.bene_dist_ref FROM beneficiariesandassessments b
JOIN disasterevents d ON b.bene_dist_ref = d.distregistry
WHERE d.haz_level IN ('Severity-4', 'Severity-5');

SELECT COUNT(DISTINCT b.bene_dist_ref) FROM beneficiariesandassessments b
JOIN disasterevents d ON b.bene_dist_ref = d.distregistry
WHERE d.haz_level IN ('Severity-4', 'Severity-5');

SELECT COUNT(*) FROM operations o
JOIN coordinationandevaluation ce ON o.opsregistry = ce.coordopsref
WHERE ce.safety_ranking = 'High Risk' OR ce.secincidentcount > 5;
